window.kbPageData["views/entry/k-a24ddb618deb5e16"] = {"key":"entry/k-a24ddb618deb5e16","state":{"route":"entry/k-a24ddb618deb5e16"},"node":{"id":"k-a24ddb618deb5e16","mode":"k","title":"匀加速直线运动的平均速度","type":"原理与机制","domain":"数学","reading":"","intro":"","priority":100,"aliases":["匀加速直线运动的平均速度等于初末速度的算术平均值","匀加速直线运动的平均速度公式"],"qs":["国考 2023 副省级 行测#72","国考 2023 地市级 行测#66"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":1,"directorySummary":"匀加速直线运动中，任一时段的平均速度等于该时段初速度与末速度的算术平均值。","review":{"definition":"匀加速直线运动中，任一时段的平均速度等于该时段初速度与末速度的算术平均值。","explanation":"加速度恒定时，速度随时间线性变化，因此时段内的平均速度可由两个端点求得。本题设甲出发时速度为1、乙的恒定速度为2。8：00至10：00两人用时相同，且甲在10：00追上乙，故两人这段路程相同，甲的平均速度为2，10：00的速度为3。甲的速度每小时增加1，11：00的速度为4，因此A、B两地相距3×(1+4)÷2＝7.5个距离单位。乙用时7.5÷2＝3.75小时，于11：45到达，选B。","references":[],"evidence":"10：00时甲的速度为2×2-1=3","disposition":"独立词条","basis":"据原题和解析编释。","title":"匀加速直线运动的平均速度","related":[],"examFocus":{"国考 2023 副省级 行测#72":"结合追上时两人的路程关系，用匀加速运动的平均速度分析甲从出发到终点的路程。"}},"readings":[{"origin":"k-a24ddb618deb5e16","title":"匀加速直线运动的平均速度","qs":["国考 2023 地市级 行测#66"],"definition":"匀加速直线运动中，任一时段的平均速度等于该时段初速度与末速度的算术平均值。","explanation":"加速度恒定时，速度随时间线性变化，因此时段内的平均速度可由两个端点求得。本题设甲出发时速度为1、乙的恒定速度为2。8：00至10：00两人用时相同，且甲在10：00追上乙，故两人这段路程相同，甲的平均速度为2，10：00的速度为3。甲的速度每小时增加1，11：00的速度为4，因此A、B两地相距3×(1+4)÷2＝7.5个距离单位。乙用时7.5÷2＝3.75小时，于11：45到达，选B。","evidence":"10：00时甲的速度为2×2-1=3","doubt":"","references":[]},{"origin":"k-d5433df717dca546","title":"匀加速直线运动的平均速度","qs":["国考 2023 副省级 行测#72"],"definition":"匀加速直线运动中，任一时段的平均速度等于该时段初速度和末速度的算术平均值。","explanation":"速度随时间线性增加，因此可以用时段两端的速度求平均速度。设甲、乙出发时的速度分别为1和2。10：00甲追上乙，两人在前两小时走过的路程相同，所以甲在这段时间的平均速度为2，10：00的速度为3。甲每小时速度增加1，11：00到达B地时速度为4。全程路程为3×(1+4)÷2＝7.5，乙用时7.5÷2＝3.75小时，于11：45到达，对应B项。","evidence":"该时段甲的平均速度=乙的速度","doubt":"","references":[]}]},"questions":{"国考 2023 副省级 行测#72":{"paper":"国考 2023 副省级 行测","n":72,"mod":"数量关系","src":["503793642e845de9795f.pdf",13],"asrc":["ecade1ff5af69283232e.pdf",22],"card":"b609151a69bc0724c0b91316","links":[{"id":"k-a24ddb618deb5e16","role":"解题依据","why":"匀加速直线运动在任一时段的平均速度等于该时段初、末速度的算术平均值。"}]},"国考 2023 地市级 行测#66":{"paper":"国考 2023 地市级 行测","n":66,"mod":"数量关系","src":["64bc3a15d27a04e94940.pdf",12],"asrc":["f3ab652d8e31c5bbdabc.pdf",20],"card":"497a6e432b646866db795414","links":[{"id":"k-a24ddb618deb5e16","role":"解题依据","why":"由追及前的平均速度和初速度反推追及时的速度，再求后续时段的平均速度。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-a24ddb618deb5e16":[["国考 2023 副省级 行测#72","国考 2023 地市级 行测#66"]]}};
